WITH with_windows AS (SELECT id, account_id, amount, merchant, is_flagged, LAG(amount, 1, 0) OVER (PARTITION BY merchant ORDER BY txn_time, id) AS prev_amount, FIRST_VALUE(merchant) IGNORE NULLS OVER (ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_merchant FROM transactions), enriched AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY account_id ORDER BY amount, id) AS event_seq, AVG(amount) OVER (PARTITION BY merchant, account_id ORDER BY amount, id ROWS BETWEEN 5 PRECEDING AND 1 PRECEDING) AS amount_avg_5_prior, SUM(prev_amount) OVER (PARTITION BY account_id ORDER BY prev_amount, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_prev_amount FROM with_windows WHERE prev_amount >= 1000), kept_keys AS (SELECT account_id, id FROM enriched INTERSECT ALL SELECT account_id, id FROM transactions WHERE txn_type <> 'FEE'), reconciled AS (SELECT s.* FROM enriched s JOIN kept_keys k ON s.account_id = k.account_id AND s.id = k.id), filtered AS (SELECT account_id, amount, merchant, is_flagged, prev_amount, event_seq, running_prev_amount, CASE WHEN prev_amount >= 4400 THEN 'High' WHEN prev_amount >= 700 THEN 'Medium' ELSE 'Low' END AS prev_amount_band, COALESCE(merchant, 'DIRECT') AS merchant_filled FROM reconciled WHERE merchant IS NOT DISTINCT FROM 'Grab' AND amount < 2100), valid AS (SELECT amount, merchant, is_flagged, prev_amount, prev_amount_band, merchant_filled, running_prev_amount * event_seq AS running_prev_amount_times_event_seq, COALESCE(merchant, 'OTHER') AS merchant_filled_2 FROM filtered WHERE merchant IS NOT NULL), report AS (SELECT amount, merchant, prev_amount, prev_amount_band, merchant_filled, running_prev_amount_times_event_seq, merchant_filled_2 FROM valid ORDER BY merchant DESC NULLS FIRST) SELECT amount, merchant, prev_amount, prev_amount_band, merchant_filled, CASE WHEN merchant RLIKE '^(Grab|Starbucks)$' THEN 'GROUP_A' ELSE 'GROUP_B' END AS merchant_zone FROM report
